mapper.select:
select

from order_item_discounts oid
where oid.id = #{id,jdbcType=BIGINT}

select

from order_item_discounts oid
where oid.order_item_id = #{orderItemId,jdbcType=BIGINT}
  and oid.discount_type = #{discountType,jdbcType=VARCHAR}
order by oid.created_at asc, oid.id asc

select oid.order_item_id as oid_order_item_id, min(oid.promotion_id) as oid_promotion_id, max(oid.promotion_code) as oid_promotion_code, max(oid.promotion_name) as oid_promotion_name, max(oid.discount_type) as oid_discount_type, max(oid.discount_value) as oid_discount_value, sum(oid.discount_amount) as oid_discount_amount, min(oid.created_at) as oid_created_at from order_item_discounts oid where oid.promotion_id = #{promotionId,jdbcType=BIGINT}
and oid.created_at >= #{from,jdbcType=TIMESTAMP}
and oid.created_at <= #{to,jdbcType=TIMESTAMP}
group by oid.order_item_id order by oid.order_item_id asc
